wolfermans.com.apply:
const input = document.querySelector('input#promotionCode'); 

try{
  input.dispatchEvent(new Event('input', {bubbles: true}));
  input.dispatchEvent(new Event('change'));
  input.dispatchEvent(new Event('keyup'));
  input.dispatchEvent(new Event('blur'));
  input.dispatchEvent(new Event('focus'));
  
  setTimeout(() => {
    document.querySelector('#btnApplyPromotion').click();
  },500);
}catch(e){
  document.querySelector('#promoCode').dispatchEvent(new Event('input', {bubbles: true}));
  document.querySelector('#promoCode').dispatchEvent(new Event('change'));
  document.querySelector('#applyPromotionBtn').click();
  setTimeout(function(){}, 4000);
}
